}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n;
    vector<string> words(n);
    for (auto& w : words) cin >> w;
    cin >> m;
    vector<string> queries(m);
    for (auto& q : queries) cin >> q;
    vector<bool> ans = answerQueries(words, queries);
    for (size_t i = 0; i < ans.size(); i++) cout << (ans[i] ? "true" : "false") << (i + 1 < ans.size() ? ' ' : '\n');
    return 0;
}

