import java.util.*;
import java.io.*;

public class Main {
    static boolean[] answerQueries(String[] words, String[] queries) {
        // Write your solution here
        return new boolean[queries.length];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String[] words = br.readLine().trim().split("\\s+");
        int m = Integer.parseInt(br.readLine().trim());
        String[] queries = br.readLine().trim().split("\\s+");
        boolean[] ans = answerQueries(words, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) sb.append(ans[i] ? "true" : "false").append(i + 1 < ans.length ? " " : "\n");
        System.out.print(sb);
    }
}
